mapper.select:
SELECT k.knowledge_point_owner_user_id, k.knowledge_point_id, k.knowledge_point_name, k.knowledge_point_code, k.knowledge_point_parent_id, k.knowledge_point_subject, k.knowledge_point_grade_level, k.knowledge_point_grade, k.knowledge_point_description, k.knowledge_point_sort_order, k.knowledge_point_status, k.knowledge_point_content_type, k.create_time, k.update_time FROM edu_knowledge_point k
AND k.knowledge_point_subject = #{subject}
AND k.knowledge_point_grade_level = #{gradeLevel}
AND k.knowledge_point_grade = #{grade}
AND k.knowledge_point_status = 1
AND (k.knowledge_point_owner_user_id IS NULL OR k.knowledge_point_owner_user_id = #{scope.ownerPredicate})
ORDER BY k.knowledge_point_sort_order ASC, k.knowledge_point_id ASC

SELECT k.knowledge_point_owner_user_id, k.knowledge_point_id, k.knowledge_point_name, k.knowledge_point_code, k.knowledge_point_parent_id, k.knowledge_point_subject, k.knowledge_point_grade_level, k.knowledge_point_grade, k.knowledge_point_description, k.knowledge_point_sort_order, k.knowledge_point_status, k.knowledge_point_content_type, k.create_time FROM edu_knowledge_point k
AND ( k.knowledge_point_name LIKE CONCAT('%', #{keyword}, '%') OR k.knowledge_point_code LIKE CONCAT('%', #{keyword}, '%') )
AND k.knowledge_point_subject = #{subject}
AND k.knowledge_point_status = 1
AND (k.knowledge_point_owner_user_id IS NULL OR k.knowledge_point_owner_user_id = #{scope.ownerPredicate})
ORDER BY k.knowledge_point_sort_order ASC, k.knowledge_point_id ASC LIMIT #{limit}

SELECT k.knowledge_point_id, k.knowledge_point_name, k.knowledge_point_code, k.knowledge_point_parent_id, k.knowledge_point_subject, k.knowledge_point_grade_level, k.knowledge_point_grade, k.knowledge_point_description, k.knowledge_point_sort_order, k.knowledge_point_status, k.create_time, CASE WHEN k.knowledge_point_content IS NOT NULL AND k.knowledge_point_content <> '' THEN 1 ELSE 0 END AS has_content, (SELECT COUNT(*) FROM edu_knowledge_file f WHERE f.knowledge_point_id = k.knowledge_point_id AND f.knowledge_file_status = 1) AS file_count FROM edu_knowledge_point k
AND ( k.knowledge_point_name LIKE CONCAT('%', #{keyword}, '%') OR k.knowledge_point_code LIKE CONCAT('%', #{keyword}, '%') )
AND k.knowledge_point_subject = #{subject}
AND k.knowledge_point_grade_level = #{gradeLevel}
AND k.knowledge_point_grade = #{grade}
AND k.knowledge_point_status = 1
AND (k.knowledge_point_owner_user_id IS NULL OR k.knowledge_point_owner_user_id = #{scope.ownerPredicate})
ORDER BY k.knowledge_point_sort_order ASC, k.knowledge_point_id ASC
